import sys
sys.path.insert(0, 'docs/features/sequencias-customizadas')
import research_compare as rc
songs = rc.load()

def match_lower_window(song, chords):
    alvo = [c.lower() for c in chords]
    cifra = [c.lower() for c in song['cifra']]
    n = len(alvo)
    if n == 0 or len(cifra) < n:
        return False
    if not any(cifra[i:i+n] == alvo for i in range(len(cifra)-n+1)):
        return False
    return set(cifra) <= set(alvo)

def match_lower_substr(song, chords):
    s = ';'.join(chords).lower()
    acorde = ';'.join(song['cifra']).lower()
    if s not in acorde:
        return False
    toks = acorde.split(';')
    return all(l in s.split(';') for l in toks)

for key,(id_seq,chords) in rc.SEQUENCIAS.items():
    tag = set(s['id'] for s in songs if rc.match_tag(s,id_seq))
    lw = set(s['id'] for s in songs if match_lower_window(s,chords))
    ls = set(s['id'] for s in songs if match_lower_substr(s,chords))
    print(key, 'tag',len(tag),'lower_window',len(lw),'equal',tag==lw,'| lower_substr',len(ls),'equal',tag==ls,
          'extras_w',len(lw-tag),'missing_w',len(tag-lw),'extras_s',len(ls-tag))
    if lw != tag:
        print('   extra ids:', list(lw-tag)[:5], 'missing:', list(tag-lw)[:5])
